    def feed(state, data):
        if state['status'] != 'open':
            return
        pending = state['pending'] + list(data)
        index = 0
        total = len(pending)
        count = 0
        while index < total:
            first = pending[index]
            if first < 128:
                index += 1
                count += 1
            elif first < 192:
                state['pending'] = []
                state['status'] = 'error'
                return
            elif first < 224:
                length = 2
                low = 128
                high = 191
            elif first < 240:
                length = 3
                if first < 226:
                    low = 128
                    high = 191
                elif first == 226:
                    low = 128
                    high = 159
                elif first < 237:
                    low = 128
                    high = 191
                elif first == 237:
                    low = 128
                    high = 159
                else:
                    low = 128
                    high = 191
            elif first < 248:
                length = 4
                if first == 240:
                    low = 144
                    high = 191
                elif first < 244:
                    low = 128
                    high = 191
                elif first == 244:
                    low = 128
                    high = 143
                else:
                    low = 128
                    high = 191
            else:
                state['pending'] = []
                state['status'] = 'error'
                return
            if index + length > total:
                break
            valid = True
            for offset in range(1, length):
                byte = pending[index + offset]
                if byte < low or byte > high:
                    valid = False
                    break
                if offset == 1:
                    low = 128
                    high = 191
            if not valid:
                state['pending'] = []
                state['status'] = 'error'
                return
            index += length
            count += 1
        state['pending'] = pending[index:]
        state['count'] += count

    def finish(state):
        if state['status'] != 'open':
            return
        if len(state['pending']) != 0:
            state['pending'] = []
            state['status'] = 'error'
        else:
            state['status'] = 'finished'

    def reset(state):
        state['count'] = 0
        state['status'] = 'open'
        state['pending'] = []

    state = {'count': 0, 'status': 'open', 'pending': []}
    for event in context['events']:
        operation = event['op']
        if operation == 'feed':
            feed(state, event['bytes'])
        elif operation == 'finish':
            finish(state)
        elif operation == 'reset':
            reset(state)
    return {'count': state['count'], 'status': state['status']}
